// One item: what the buyer got, and whether the chain agrees. Every hash is full; nothing here is taken on trust.
const d = $('Get demand').last().json.demand;
let j = {};
try { j = $('Explorer').first().json.job || {}; } catch (e) { j = {}; }
const a = $json || {};
return [{ json: {
  demand: d.id, state: d.state, why: d.why || null, class: d.class, need: d.need || null, buyer_label: d.buyer_label || null,
  seller: d.seller || null, handshake: d.handshake_id || null, job_id: d.job_id || null, chain_id: d.chainId || null,
  grade: d.grade ? { verdict: d.grade.verdict, checks: d.grade.checks } : null,
  settle: d.ending ? { transition: d.ending.transition, tx: d.ending.tx, link: d.ending.tx ? `https://www.taifoon.io/scan/36927/tx/${d.ending.tx}` : null } : null,
  doer: j.doer || null, payee: j.payee ? { address: j.payee.address, whose: j.payee.whose, paid: j.payee.paid } : null, doer_is_payee: j.doer_is_payee ?? null,
  txs: (j.txs || []).map((t) => ({ role: t.role, hash: t.hash, link: t.link })),
  attestation: d.ending && d.ending.tx ? { verdict: a.verdict ?? null, summary: a.summary ?? null, checks: a.checks ?? null } : { verdict: 'UNVERIFIED', summary: 'no settle transaction to check: the demand ended ' + d.state, checks: null },
  explorer: (j.links || {}).page || `https://www.taifoon.io/scan/jobs/${d.id}`,
} }];
